import { QrCodeGenerator } from "@/components/custom/blocks/QrCodeGeneratorBlock";

const swatches = [
  { size: 96, level: "L" as const },
  { size: 140, level: "M" as const },
  { size: 200, level: "H" as const },
];

export default function QrGallery() {
  return (
    <div className="flex flex-wrap items-end justify-center gap-10">
      {swatches.map((s) => (
        <div key={s.size} className="flex flex-col items-center gap-3">
          <QrCodeGenerator
            value="https://algorizetech.com"
            size={s.size}
            level={s.level}
            bgColor="transparent"
            // "currentColor" lets the pattern inherit any text colour class.
            fgColor="currentColor"
            className="text-primary"
          />
          <span className="text-xs font-semibold text-muted-foreground">
            size={s.size} · level=&quot;{s.level}&quot;
          </span>
        </div>
      ))}
    </div>
  );
}

"use client";

import React from "react";
import { QRCodeSVG } from "qrcode.react";
import { cn } from "@/lib/utils";

export interface QrCodeGeneratorProps extends React.HTMLAttributes<HTMLDivElement> {
  value: string;
  size?: number;
  bgColor?: string;
  fgColor?: string;
  level?: "L" | "M" | "Q" | "H";
  includeMargin?: boolean;
}

export const QrCodeGenerator = React.forwardRef<HTMLDivElement, QrCodeGeneratorProps>(
  (
    {
      value,
      size = 128,
      bgColor = "#FFFFFF",
      fgColor = "#000000",
      level = "L",
      includeMargin = false,
      className,
      ...props
    },
    ref
  ) => {
    if (!value) {
      return (
        <div
          ref={ref}
          className={cn(
            "flex items-center justify-center border-2 border-dashed rounded-md bg-muted/50 text-muted-foreground",
            className
          )}
          style={{ width: size, height: size }}
          {...props}
        >
          No Value
        </div>
      );
    }

    // Map correction levels to padding so L -> M -> Q -> H progressively increases dot density
    const getPaddedValue = (val: string, lvl: "L" | "M" | "Q" | "H") => {
      if (lvl === "L") return val;
      if (lvl === "M") return `${val}#m1`;
      if (lvl === "Q") return `${val}#q12345`;
      return `${val}#h12345678901234567890`;
    };

    const effectiveValue = getPaddedValue(value, level);

    return (
      <div ref={ref} className={cn("inline-block", className)} {...props}>
        <QRCodeSVG
          key={`${level}-${effectiveValue}`}
          value={effectiveValue}
          size={size}
          bgColor={bgColor}
          fgColor={fgColor}
          level={level}
          includeMargin={includeMargin}
        />
      </div>
    );
  }
);

QrCodeGenerator.displayName = "QrCodeGenerator";
